contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // read minDelay and timestamp for the computed id BEFORE calling schedule
        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 tsBefore = c.getTimestamp(id);

        // Attempt schedule and record whether it reverted
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: compute observed properties
        uint256 tsAfter = c.getTimestamp(id);
        bool isOp = c.isOperation(id);
        bool isPending = c.isOperationPending(id);
        bool isReady = c.isOperationReady(id);
        bool isDone = c.isOperationDone(id);

        // General rule asserted:
        // If delay < minDelay then schedule must revert (operation unchanged).
        // If delay >= minDelay and schedule did not revert then operation becomes scheduled (isOperation true)
        // and timestamp changed from previous to a value > 0. We cannot rely on exact block.timestamp value in assertion,
        // so assert monotonicity and consistency with isOperation.
        assert(
            (
                delay < minDelay && reverted && tsAfter == tsBefore && !isOp
            ) || (
                delay >= minDelay && !reverted && isOp && tsAfter > 0 && tsAfter != tsBefore
            )
        );
    }

    // receive to allow sending Ether to this test contract if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: cancel behavior for pending vs non-pending operations
    // We take parameters to construct an operation id and a delay that is >= minDelay.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // require a workable delay bound so scheduling should be allowed
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay must be >= minDelay");

        // compute id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // ensure operation is not already scheduled initially
        bool initiallyPending = c.isOperationPending(id);

        // If not pending initially: scheduling it should succeed (msg.sender must have PROPOSER_ROLE, but this contract may not).
        // Instead, we try scheduling and record whether it reverted.
        bool schedReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            schedReverted = false;
        } catch {
            schedReverted = true;
        }

        // After attempting schedule, check pending status
        bool nowPending = c.isOperationPending(id);

        // Try cancel and record whether it reverts
        bool cancelReverted;
        try c.cancel(id) {
            cancelReverted = false;
        } catch {
            cancelReverted = true;
        }

        // After cancel attempt, check operation existence
        bool afterCancelIsOp = c.isOperation(id);

        // General rule asserted succinctly:
        // If operation became pending (nowPending == true) and cancel did not revert, then afterCancelIsOp must be false.
        // If operation was not pending (nowPending == false), then cancel must revert.
        assert(
            (nowPending && !cancelReverted && !afterCancelIsOp) || (!nowPending && cancelReverted)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: when execute(...) does not revert, afterwards the operation is marked done
    // and the caller (this contract) must have EXECUTOR_ROLE.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // require delay at least minDelay so scheduling can succeed
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay >= minDelay");

        // compute id and schedule the operation using the contract's schedule (may revert if no PROPOSER_ROLE)
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        bool schedReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            schedReverted = false;
        } catch {
            schedReverted = true;
        }

        // If scheduling reverted we cannot proceed to execute successfully, so require it succeeded for the rest of the test
        require(!schedReverted, "scheduling must succeed for this test");

        // Fast-forwarding is not available; ensure operation is ready by using delay == 0 or assuming block.timestamp already >= scheduled timestamp
        // To ensure ready, require delay == 0.
        require(delay == 0, "delay must be 0 to make operation ready immediately");

        // Try executing and capture whether it reverted
        bool execReverted;
        try c.execute{value: value}(target, value, data, predecessor, salt) {
            execReverted = false;
        } catch {
            execReverted = true;
        }

        // After attempting execute, check isOperationDone and whether this contract has EXECUTOR_ROLE
        bool done = c.isOperationDone(id);
        bool isExecutor = c.hasRole(c.EXECUTOR_ROLE(), address(this));

        // General rule: if execute did not revert then the operation must be done and the caller must have EXECUTOR_ROLE
        assert(execReverted || (done && isExecutor));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing minimal steps: schedule an operation (must succeed), ensure it's ready by requiring delay==0,
    // then attempt execute and assert that if execute did not revert then the operation is done.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // This test requires delay == 0 so that after scheduling the operation is immediately ready.
        require(delay == 0, "delay==0");

        // Compute id using public hashOperation
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Attempt to schedule. If schedule reverts (no PROPOSER_ROLE) we cannot proceed: require it succeeds.
        c.schedule(target, value, data, predecessor, salt, delay);

        // Try executing and record whether it reverted.
        bool execReverted;
        try c.execute{value: value}(target, value, data, predecessor, salt) {
            execReverted = false;
        } catch {
            execReverted = true;
        }

        // Read whether the operation is done using the public view.
        bool done = c.isOperationDone(id);

        // General property: if execute did not revert then the operation must be done.
        assert(execReverted || done);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: schedule with delay==0, then try execute; assert that either schedule reverted or (execute reverted) or operation is done.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(delay == 0, "need zero delay");

        // compute id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Try scheduling and record if it reverted. Scheduling changes state if it succeeds.
        bool scheduleReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            scheduleReverted = false;
        } catch {
            scheduleReverted = true;
        }

        // Try executing and record if it reverted.
        bool execReverted;
        try c.execute{value: value}(target, value, data, predecessor, salt) {
            execReverted = false;
        } catch {
            execReverted = true;
        }

        // Read whether the operation is done using public view
        bool done = c.isOperationDone(id);

        // General rule: if schedule succeeded and execute succeeded then operation must be done.
        assert(scheduleReverted || execReverted || done);
    }

    receive() external payable {}
}
